ons.className='result-actions';buttons.append(actionButton(t.play,x.id,'play'),actionButton(t.next,x.id,'next'),actionButton(t.append,x.id,'append'));li.append(name,meta,buttons);return li}))}async function stream(){streamAbort?.abort();streamAbort=new AbortController;try{const r=await fetch('/remote/api/events',{headers:headers(),signal:streamAbort.signal});if(!r.ok)throw 0;login.hidden=true;player.hidden=false;const reader=r.body.getReader(),decoder=new TextDecoder;let buffer='';for(;;){const x=await reader.read();if(x.done)throw 0;buffer+=decoder.decode(x.value,{stream:true});let end;while((end=buffer.indexOf('\n\n'))>=0){const event=buffer.slice(0,end);buffer=buffer.slice(end+2);const data=event.split('\n').find(line=>line.startsWith('data: '));if(data)render(JSON.parse(data.slice(6)))}}}catch(e){if(e.name==='AbortError')return;player.hidden=true;login.hidden=false;setTimeout(()=>{if(key)stream()},2000)}}connect.onclick=()=>{key=token.value.trim();sessionStorage.orynivoRemoteToken=key;artKey='';stream()};document.querySelectorAll('[data-cmd]').forEach(b=>b.onclick=()=>command(b.dataset.cmd));seek.onchange=()=>command('seek',+seek.value);volume.onchange=()=>command('volume',+volume.value);searchForm.onsubmit=e=>{e.preventDefault();runSearch()};if(key)connect.click();
