async function browseArtists(){libraryLevel='artists';libraryArtist=null;libraryBack.hidden=true;libraryTitle.textContent=libraryWords.artists;const q=libraryFilter.value.trim();const r=await fetch('/remote/api/library/artists?q='+encodeURIComponent(q)+'&limit=150',{headers:headers()});if(!r.ok)return;const rows=await r.json();libraryList.replaceChildren(...rows.map(x=>libraryRow(x.name,x.source,()=>browseAlbums(x))))}
